-- Generated by prepare-box-rewards.py. Preview by default; player inventories remain untouched.
\set ON_ERROR_STOP on
\if :{?apply}
\else
\set apply false
\endif
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';
SELECT set_config('mu.expected_database', :'expected_database', true);
DO $$ BEGIN
 IF current_database() <> current_setting('mu.expected_database') THEN
  RAISE EXCEPTION 'Database does not match explicitly selected maintenance target';
 END IF;
END $$;
CREATE TEMP TABLE approved_plan ON COMMIT DROP AS SELECT $plan$__APPROVED_PLAN__$plan$::jsonb AS value;
CREATE TEMP TABLE reward_plan ON COMMIT DROP AS
 SELECT r.* FROM approved_plan, jsonb_to_recordset(value->'rewards') AS r(
 id uuid, description text, level smallint, chance double precision, type integer,
 minimum smallint, maximum smallint, money integer, second double precision,
 skill double precision, jewelry boolean, effect integer, items jsonb, luck double precision, "suppressAdd" boolean);
CREATE TEMP TABLE bonus_plan ON COMMIT DROP AS
 SELECT b.* FROM approved_plan, jsonb_to_recordset(value->'bonuses') AS b(
 id uuid, bonus text, map smallint, monster smallint, name text, level smallint);
CREATE TEMP TABLE selected_configuration ON COMMIT DROP AS
 SELECT "Id" AS id FROM config."GameConfiguration"
 WHERE "Id"='00000001-0001-0000-0000-000000000000';
CREATE TEMP TABLE source_box ON COMMIT DROP AS
 SELECT i."Id" AS id FROM config."ItemDefinition" i, selected_configuration c
 WHERE i."GameConfigurationId"=c.id AND i."Group"=14 AND i."Number"=11;
CREATE TEMP TABLE reward_items ON COMMIT DROP AS
 SELECT r.id AS group_id, i."Id" AS item_id, i."MaximumSockets" AS sockets, r.type
 FROM reward_plan r CROSS JOIN LATERAL jsonb_array_elements(r.items) e
 JOIN config."ItemDefinition" i ON i."Group"=(e->>0)::integer AND i."Number"=(e->>1)::integer
 JOIN selected_configuration c ON i."GameConfigurationId"=c.id;
CREATE TEMP TABLE bonus_targets ON COMMIT DROP AS
 SELECT p.*, m."Id" AS map_id, n."Id" AS monster_id FROM bonus_plan p
 JOIN config."GameMapDefinition" m ON m."Number"=p.map
 JOIN selected_configuration c ON m."GameConfigurationId"=c.id
 JOIN config."MonsterDefinition" n ON n."Number"=p.monster AND n."GameConfigurationId"=c.id;
DO $$ BEGIN
 IF (SELECT count(*) FROM selected_configuration)<>1 OR (SELECT count(*) FROM source_box)<>1 THEN
  RAISE EXCEPTION 'Expected exactly one selected Season 6 configuration and source box'; END IF;
 IF (SELECT count(*) FROM reward_items)<>(SELECT sum(jsonb_array_length(items)) FROM reward_plan) THEN
  RAISE EXCEPTION 'Reward item missing or ambiguous'; END IF;
 IF EXISTS (SELECT FROM reward_items WHERE type=2 AND sockets>0) THEN
  RAISE EXCEPTION 'Socket item in approved Kundun rewards'; END IF;
 IF (SELECT count(*) FROM bonus_targets)<>(SELECT count(*) FROM bonus_plan) THEN
  RAISE EXCEPTION 'Bonus monster or map missing or ambiguous'; END IF;
 IF EXISTS (SELECT FROM reward_plan GROUP BY level HAVING abs(sum(chance)-1)>1e-12) THEN
  RAISE EXCEPTION 'Reward probabilities must total 100 percent'; END IF;
 IF (SELECT count(*) FROM config."GameServerDefinition" s, selected_configuration c
     WHERE s."GameConfigurationId"=c.id AND s."ServerID"=0)<>1 THEN
  RAISE EXCEPTION 'Expected exactly one Server 1'; END IF;
END $$;

-- Replace only opening rules for the ten explicitly selected source levels.
DELETE FROM config."ItemDropItemGroup" d USING source_box b
 WHERE d."ItemDefinitionId"=b.id AND d."SourceItemLevel" IN (SELECT DISTINCT level FROM reward_plan);
INSERT INTO config."ItemDropItemGroup"
 ("Id","Description","Chance","ItemType","ItemDefinitionId","SourceItemLevel",
  "MinimumLevel","MaximumLevel","MoneyAmount","RequiredCharacterLevel","DropEffect",
  "ExcellentSecondOptionChance","SkillChance","GuaranteeJewelryOption","LuckChance","SuppressAdditionalOption")
 SELECT r.id,r.description,r.chance,r.type,b.id,r.level,r.minimum,r.maximum,r.money,0,r.effect,r.second,r.skill,r.jewelry,r.luck,r."suppressAdd"
 FROM reward_plan r CROSS JOIN source_box b;
INSERT INTO config."ItemDropItemGroupItemDefinition" ("ItemDropItemGroupId","ItemDefinitionId")
 SELECT group_id,item_id FROM reward_items;

-- Replace this configuration's small-bonus pool; retain the item definitions.
DELETE FROM config."DropItemGroup" d USING selected_configuration c
 WHERE d."GameConfigurationId"=c.id AND d."ItemType"=7;

CREATE TEMP TABLE excluded_items ON COMMIT DROP AS
 SELECT i."Id" AS id FROM approved_plan p
 CROSS JOIN LATERAL jsonb_array_elements(p.value->'excludedItems') e
 JOIN config."ItemDefinition" i ON i."Group"=(e->>0)::integer AND i."Number"=(e->>1)::integer
 JOIN selected_configuration c ON i."GameConfigurationId"=c.id;
UPDATE config."ItemDefinition" i SET "DropsFromMonsters"=false
 WHERE i."Id" IN (SELECT id FROM excluded_items) OR i."Id" IN (SELECT id FROM source_box);
CREATE TEMP TABLE removed_bonus_groups ON COMMIT DROP AS
 SELECT DISTINCT g."Id" AS id FROM config."DropItemGroup" g
 JOIN config."DropItemGroupItemDefinition" j ON j."DropItemGroupId"=g."Id"
 JOIN selected_configuration c ON g."GameConfigurationId"=c.id
 WHERE j."ItemDefinitionId" IN (SELECT id FROM excluded_items)
 OR (j."ItemDefinitionId" IN (SELECT id FROM source_box)
     AND coalesce(g."ItemLevel",0) IN (SELECT jsonb_array_elements_text(value->'excludedWrapperLevels')::smallint FROM approved_plan));
DELETE FROM config."DropItemGroupItemDefinition" j
 WHERE j."DropItemGroupId" IN (SELECT id FROM removed_bonus_groups)
 AND (j."ItemDefinitionId" IN (SELECT id FROM excluded_items)
      OR j."ItemDefinitionId" IN (SELECT id FROM source_box));
DELETE FROM config."GameMapDefinitionDropItemGroup" j
 WHERE j."DropItemGroupId" IN (SELECT id FROM removed_bonus_groups)
 AND NOT EXISTS (SELECT FROM config."DropItemGroupItemDefinition" i WHERE i."DropItemGroupId"=j."DropItemGroupId");
DELETE FROM config."MonsterDefinitionDropItemGroup" j
 WHERE j."DropItemGroupId" IN (SELECT id FROM removed_bonus_groups)
 AND NOT EXISTS (SELECT FROM config."DropItemGroupItemDefinition" i WHERE i."DropItemGroupId"=j."DropItemGroupId");

INSERT INTO config."DropItemGroup"
 ("Id","GameConfigurationId","Description","Chance","ItemLevel","ItemType","MonsterId")
 SELECT t.id,c.id,'Approved bonus: '||t.bonus||' / '||t.name,1,t.level,7,t.monster_id
 FROM bonus_targets t CROSS JOIN selected_configuration c;
INSERT INTO config."DropItemGroupItemDefinition" ("DropItemGroupId","ItemDefinitionId")
 SELECT t.id,b.id FROM bonus_targets t CROSS JOIN source_box b;
INSERT INTO config."GameMapDefinitionDropItemGroup" ("GameMapDefinitionId","DropItemGroupId")
 SELECT map_id,id FROM bonus_targets;
UPDATE config."GameServerDefinition" s
 SET "SmallBonusDropsEnabled"=true,"SmallBonusDropChance"=(p.value->>'totalChance')::double precision
 FROM approved_plan p,selected_configuration c
 WHERE s."GameConfigurationId"=c.id AND s."ServerID"=0;

-- Add test stock to Lumen's existing shop, preserving every other listing.
CREATE TEMP TABLE selected_shop ON COMMIT DROP AS
 SELECT n."MerchantStoreId" AS id FROM config."MonsterDefinition" n
 JOIN selected_configuration c ON n."GameConfigurationId"=c.id
 JOIN data."ItemStorage" s ON s."Id"=n."MerchantStoreId"
 WHERE n."Number"=255 AND s."AccountId" IS NULL;
CREATE TEMP TABLE shop_plan ON COMMIT DROP AS
 SELECT ('24b00002-0000-4000-8000-'||lpad(level::text,12,'0'))::uuid AS id,
 level, row_number() OVER (ORDER BY level) AS position
 FROM reward_plan WHERE level <> 1 GROUP BY level;
CREATE TEMP TABLE free_shop_slots ON COMMIT DROP AS
 SELECT slot::smallint AS slot, row_number() OVER (ORDER BY slot) AS position
 FROM generate_series(0,119) slot
 WHERE NOT EXISTS (
  SELECT FROM data."Item" i JOIN selected_shop s ON i."ItemStorageId"=s.id
  JOIN config."ItemDefinition" d ON d."Id"=i."DefinitionId"
  CROSS JOIN LATERAL generate_series(0,d."Width"-1) x
  CROSS JOIN LATERAL generate_series(0,d."Height"-1) y
  WHERE i."Id" NOT IN (SELECT id FROM shop_plan)
    AND slot=i."ItemSlot"+x+8*y);
DO $$ BEGIN
 IF (SELECT count(*) FROM selected_shop)<>1 THEN
  RAISE EXCEPTION 'Expected exactly one Lumen merchant shop without an account owner'; END IF;
 IF EXISTS (SELECT FROM config."ItemDefinition" WHERE "Id" IN (SELECT id FROM source_box)
            AND ("Width"<>1 OR "Height"<>1)) THEN
  RAISE EXCEPTION 'Test boxes must occupy one shop cell'; END IF;
 IF (SELECT count(*) FROM free_shop_slots)<10 THEN
  RAISE EXCEPTION 'Lumen shop needs ten free cells for test boxes'; END IF;
 IF EXISTS (SELECT FROM data."Item" i JOIN shop_plan p ON i."Id"=p.id
            WHERE i."ItemStorageId" IS DISTINCT FROM (SELECT id FROM selected_shop)
               OR i."DefinitionId" IS DISTINCT FROM (SELECT id FROM source_box)
               OR i."Level"<>p.level) THEN
  RAISE EXCEPTION 'Reserved test listing ID belongs to another item'; END IF;
END $$;
INSERT INTO data."Item"
 ("Id","ItemStorageId","DefinitionId","ItemSlot","Durability","Level","HasSkill","SocketCount","StorePrice","PetExperience")
 SELECT p.id,s.id,b.id,f.slot,1,p.level,false,0,1000,0
 FROM shop_plan p JOIN free_shop_slots f ON f.position=p.position
 CROSS JOIN selected_shop s CROSS JOIN source_box b
 ON CONFLICT ("Id") DO UPDATE SET "ItemSlot"=excluded."ItemSlot","StorePrice"=excluded."StorePrice";

SELECT level AS source_level,count(*) AS reward_groups,sum(chance) AS total_probability FROM reward_plan GROUP BY level ORDER BY level;
SELECT bonus,count(*) AS eligible_monsters FROM bonus_plan GROUP BY bonus ORDER BY bonus;
SELECT i."Level" AS shop_source_level,i."ItemSlot",i."StorePrice" AS purchase_price
 FROM data."Item" i JOIN shop_plan p ON p.id=i."Id" ORDER BY i."Level";
\if :apply
COMMIT;
\else
ROLLBACK;
\endif
